const fs = require("fs");
const os = require("os");
const path = require("path");

const HOST_NAME = "com.goblin.codex_local_viewer";
const repoRoot = path.resolve(__dirname, "..");
const hostPath = path.join(repoRoot, "native-host", "codex-local-viewer-host.js");

function shellQuote(value) {
  return `'${String(value).replaceAll("'", "'\\''")}'`;
}

function createLauncherScript(nodePath, targetHostPath) {
  return [
    "#!/bin/sh",
    "# Generated by goblin. Chrome Native Messaging runs with a minimal GUI environment,",
    "# so this launcher uses the absolute Node.js path captured during installation.",
    "export PATH=\"/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin:$PATH\"",
    `exec ${shellQuote(nodePath)} ${shellQuote(targetHostPath)}`,
    "",
  ].join("\n");
}

function getExtensionId() {
  const id = process.argv[2] || process.env.EXTENSION_ID;
  if (!id || !/^[a-p]{32}$/.test(id)) {
    throw new Error(
      "Chrome extension id is required. Usage: npm run install:native-host -- <extension-id>",
    );
  }
  return id;
}

function nativeHostDir() {
  if (process.platform === "darwin") {
    return path.join(os.homedir(), "Library/Application Support/Google/Chrome/NativeMessagingHosts");
  }

  if (process.platform === "linux") {
    return path.join(os.homedir(), ".config/google-chrome/NativeMessagingHosts");
  }

  throw new Error("Automatic native host install is currently implemented for macOS and Linux.");
}

function install() {
  const extensionId = getExtensionId();
  const targetDir = nativeHostDir();
  const targetPath = path.join(targetDir, `${HOST_NAME}.json`);
  const launcherPath = path.join(targetDir, HOST_NAME);
  const manifest = {
    name: HOST_NAME,
    description: "goblin native host",
    path: launcherPath,
    type: "stdio",
    allowed_origins: [`chrome-extension://${extensionId}/`],
  };

  fs.mkdirSync(targetDir, { recursive: true });
  fs.chmodSync(hostPath, 0o755);
  fs.writeFileSync(launcherPath, createLauncherScript(process.execPath, hostPath));
  fs.chmodSync(launcherPath, 0o755);
  fs.writeFileSync(targetPath, `${JSON.stringify(manifest, null, 2)}\n`);

  console.log(`Native host installed: ${targetPath}`);
  console.log(`Native host launcher: ${launcherPath}`);
  console.log(`Node executable: ${process.execPath}`);
  console.log(`Allowed extension: chrome-extension://${extensionId}/`);
}

if (require.main === module) {
  install();
}

module.exports = {
  createLauncherScript,
  nativeHostDir,
  shellQuote,
};
